 "content": "def transform(grid):
    """Mark compartments containing more than one non-background cell."""
    h, w = len(grid), len(grid[0])
    # Full uniform rows/columns are the partition dividers.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, cuts):
        out = []
        start = 0
        for cut in cuts:
            if cut >= start:
                if start < cut:
                    out.append((start, cut))
                start = cut + 1
        if start < n:
            out.append((start, n))
        return out

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    # The most frequent non-divider color is the compartment background.
    divider_cells = {(r, c) for r in sep_rows for c in range(w)} | {(r, c) for r in range(h) for c in sep_cols}
    counts = {}
    for r in range(h):
        for c in range(w):
            if (r, c) not in divider_cells:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r0, r1 in row_spans:
        row = []
        for c0, c1 in col_spans:
            marks = sum(grid[r][c] != background for r in range(r0, r1) for c in range(c0, c1))
            row.append(1 if marks > 1 else background)
        result.append(row)
    return result
